using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.InputSystem;
public partial class DungeonPrototype {
 readonly HashSet<string> pendingChests=new HashSet<string>();
 public DungeonMapSettings mapSettings;
 DungeonMapSettings ActiveMap {get{return mapSettings!=null?mapSettings:DungeonMapSettings.Current;}}
 readonly Dictionary<string,GameObject> mapEntityObjects=new Dictionary<string,GameObject>();
 readonly Dictionary<string,DungeonDoor> mapDoors=new Dictionary<string,DungeonDoor>();
 List<DungeonEntityState> mapEntityStates=new List<DungeonEntityState>();
 DungeonSaveData incomingMapTravel;
 bool LegacyObjectEnabled(string id){return ActiveMap==null||!ActiveMap.disabledLegacyObjects.Contains(id);}
 void RemoveDisabledLegacyDoors(){if(!LegacyObjectEnabled("legacy.exit")&&exitDoor!=null){Destroy(exitDoor.gameObject);exitDoor=null;}if(!LegacyObjectEnabled("corridor.door")&&zoneTwoDoor!=null){Destroy(zoneTwoDoor.gameObject);zoneTwoDoor=null;}}
 DungeonEntityState EntityState(string id){var state=mapEntityStates.Find(s=>s.id==id);if(state==null){state=new DungeonEntityState{id=id};mapEntityStates.Add(state);}return state;}
 void CreateMapEntities(){if(ActiveMap==null||ActiveMap.entities==null)return;
  foreach(var e in ActiveMap.entities.objects){if(e==null||!Open(e.cell)||mapEntityObjects.ContainsKey(e.id))continue;
   if(string.IsNullOrEmpty(e.id))continue;var root=new GameObject(e.displayName+" ["+e.id+"]");root.transform.SetParent(transform,false);root.transform.position=World(e.cell)-Vector3.up*1.5f;root.transform.rotation=Quaternion.Euler(0,e.heading*90,0);mapEntityObjects[e.id]=root;
   if(e.kind==DungeonEntityKind.NPC){var npc=e.npcCatalog!=null?Array.Find(e.npcCatalog.npcs,n=>n.id==e.npcId):null;int kind=npc!=null?Array.IndexOf(EnemyRoster.ResourceIds,npc.visualSpeciesId):-1;if(kind>=0){EnemyRoster.AddVisual(root,kind);root.AddComponent<DungeonNpcFacing>().viewCamera=view;root.transform.localScale=Vector3.one*.75f;}}
   else if(e.kind==DungeonEntityKind.Savepoint||e.kind==DungeonEntityKind.Teleport){if(e.kind==DungeonEntityKind.Savepoint){foreach(var dir in directions)if(!Open(e.cell+dir)){root.transform.position+=new Vector3(dir.x,0,dir.y)*(Cell*.5f-.2f);root.transform.rotation=Quaternion.LookRotation(new Vector3(-dir.x,0,-dir.y));break;}}var v=root.AddComponent<RefugeDeviceVisual>();v.portal=e.kind==DungeonEntityKind.Teleport;v.deviceName=e.displayName;v.Build();if(v.portal&&(e.initiallyActive||!e.requiresActivation)&&!refuge.unlockedNodes.Contains(e.id))refuge.unlockedNodes.Add(e.id);v.transferActive=refuge.unlockedNodes.Contains(e.id);}
   else if(e.kind==DungeonEntityKind.Door){root.transform.position+=root.transform.forward*Cell*.5f;var door=root.AddComponent<DungeonDoor>();door.settings=e.doorSettings!=null?e.doorSettings:exitDoorSettings;door.doorwayWidth=Cell;door.interactionDistance=Cell*.5f+.25f;door.openingTravel=corridorHeight+.2f;var panel=Box("Entity door panel",root.transform.position+Vector3.up*corridorHeight*.5f,new Vector3(Cell-.1f,corridorHeight,.15f),wall);panel.transform.SetParent(root.transform,true);panel.transform.rotation=root.transform.rotation;door.panel=panel.transform;door.blocker=panel.GetComponent<Collider>();door.Initialize();if(e.doorInitiallyOpen)door.SetOpenImmediately();mapDoors[e.id]=door;var captured=e;door.Passed+=()=>{EntityState(captured.id).opened=true;if(captured.doorKind==DungeonDoorKind.Transition)TravelMapDoor(captured);};}
   else root.AddComponent<DungeonChestVisual>().viewCamera=view;
  }RefreshMapEntityStates();
 }
 void RefreshMapEntityStates(){if(ActiveMap==null||ActiveMap.entities==null)return;foreach(var e in ActiveMap.entities.objects){GameObject root;if(!mapEntityObjects.TryGetValue(e.id,out root))continue;var visual=root.GetComponent<RefugeDeviceVisual>();if(visual!=null&&visual.portal)visual.transferActive=refuge.unlockedNodes.Contains(e.id);if(e.kind==DungeonEntityKind.Chest){root.SetActive(!(e.chestKind==DungeonChestKind.Mimic&&EntityState(e.id).opened));var chest=root.GetComponent<DungeonChestVisual>();if(chest!=null)chest.SetOpened(EntityState(e.id).opened);}DungeonDoor door;if(e.kind==DungeonEntityKind.Door&&mapDoors.TryGetValue(e.id,out door)){if(e.doorKind==DungeonDoorKind.Locked&&!HasMapKey(e.requiredKeyId)){EntityState(e.id).opened=false;door.SetClosedImmediately();}else if(e.doorInitiallyOpen||EntityState(e.id).opened)door.SetOpenImmediately();}}}
 bool MapNpcBlocks(Vector2Int cell){if(ActiveMap==null||ActiveMap.entities==null)return false;return ActiveMap.entities.objects.Exists(e=>(e.kind==DungeonEntityKind.NPC||e.kind==DungeonEntityKind.Chest||e.kind==DungeonEntityKind.Savepoint)&&e.cell==cell&&!(e.kind==DungeonEntityKind.Chest&&e.chestKind==DungeonChestKind.Mimic&&EntityState(e.id).opened));}
 bool MapDoorsBlock(Vector3 from,Vector3 to){foreach(var door in mapDoors.Values)if(door!=null&&door.Blocks(from,to))return true;return false;}
 bool HasMapKey(string id){if(ownedEquipment.Contains(id))return true;int i=Array.FindIndex(inventorySettings.items,item=>item!=null&&item.id==id);return i>=0&&itemCounts[i]>0;}
 bool FacingMapTeleport(DungeonMapEntity e){GameObject root;return mapEntityObjects.TryGetValue(e.id,out root)&&LookingToward(root.transform.TransformPoint(new Vector3(1.65f,.57f,.4f)));}
 DungeonMapEntity NearbyMapEntity(){if(ActiveMap==null||ActiveMap.entities==null)return null;foreach(var e in ActiveMap.entities.objects){if(e.kind==DungeonEntityKind.Chest&&e.chestKind==DungeonChestKind.Mimic&&EntityState(e.id).opened)continue;if(e.kind==DungeonEntityKind.Teleport){if(e.cell==position&&FacingMapTeleport(e))return e;}else if(e.kind==DungeonEntityKind.Door){DungeonDoor door;if(mapDoors.TryGetValue(e.id,out door)&&DoorInteractionAvailable(door))return e;}else if(FacingRefugeNpc(e.cell)&&FacingMapEntity(e))return e;}return null;}
 bool UpdateMapEntityInput(){if(worldDialogue.Active||IntroductionActive||battle||moving||lost||pauseOpen)return false;var k=Keyboard.current;if(k==null||!k.eKey.wasPressedThisFrame)return false;var e=NearbyMapEntity();if(e==null)return false;InteractMapEntity(e);return true;}
 void InteractMapEntity(DungeonMapEntity e){
  if(e.kind==DungeonEntityKind.NPC){var npc=e.npcCatalog!=null?Array.Find(e.npcCatalog.npcs,n=>n.id==e.npcId):null;if(e.dialogue.Length>0)worldDialogue.Begin(e.dialogue);else if(npc!=null&&npc.conversations!=null&&npc.conversations.Length>0){var state=NpcState(e.id);var text=npc.conversations[Mathf.Min(state.talks,npc.conversations.Length-1)];worldDialogue.Begin(new[]{new WorldDialogueLine(npc.displayName,text)},()=>state.talks++);}}
  else if(e.kind==DungeonEntityKind.Chest){if(EntityState(e.id).opened){message="El cofre está vacío.";return;}if(!string.IsNullOrEmpty(e.guardPlacementId)){int guard=slots.FindIndex(s=>s.placement!=null&&s.placement.id==e.guardPlacementId);if(guard>=0&&enemyObjects[guard]!=null){BeginEncounter(guard);message="El guardián protege este cofre.";return;}if(guard<0&&!System.Linq.Enumerable.Any(defeatedEnemies.Values,r=>r.placementId==e.guardPlacementId)){message="No se puede verificar el guardián del cofre.";return;}}if(pendingChests.Add(e.id))StartCoroutine(OpenMapChest(e));}
  else if(e.kind==DungeonEntityKind.Savepoint){if(e.heal)hp=MaximumHP;bool saved=!e.save||SaveDungeonGame();var v=mapEntityObjects[e.id].GetComponent<RefugeDeviceVisual>();v.ShowSaveResult(saved);worldDialogue.Begin(new[]{new WorldDialogueLine("SISTEMA",saved?(e.save?"Progreso registrado.":"Integridad restaurada."):"No se pudo guardar la partida.")});}
  else if(e.kind==DungeonEntityKind.Door){if(e.doorKind==DungeonDoorKind.Locked&&!HasMapKey(e.requiredKeyId)){worldDialogue.Begin(new[]{new WorldDialogueLine("SISTEMA","Puerta bloqueada. Necesitas su llave.")});return;}mapDoors[e.id].OpenDoor();}
  else ExamineMapNode(e);
 }
 System.Collections.IEnumerator OpenMapChest(DungeonMapEntity e){var chest=mapEntityObjects[e.id].GetComponent<DungeonChestVisual>();if(chest!=null){chest.SetOpened(true);while(chest!=null&&chest.IsOpening)yield return null;}
  bool received=false;
  if(e.chestKind==DungeonChestKind.Mimic)received=TriggerSpecialEncounter(e.mimicPlacementId);
  else received=string.IsNullOrEmpty(e.contentId)||AcquireItem(e.contentId,e.quantity);
  if(received){EntityState(e.id).opened=true;if(e.chestKind==DungeonChestKind.Mimic)mapEntityObjects[e.id].SetActive(false);if(string.IsNullOrEmpty(e.contentId)&&e.chestKind!=DungeonChestKind.Mimic)message="El cofre está vacío.";}
  else {if(chest!=null)chest.SetOpened(false);if(e.chestKind!=DungeonChestKind.Mimic)worldDialogue.Begin(new[]{new WorldDialogueLine("SISTEMA","No puedes recoger el contenido. Revisa el espacio del inventario.")});}
  pendingChests.Remove(e.id);
 }
 void ExamineMapNode(DungeonMapEntity e){bool first=!refuge.unlockedNodes.Contains(e.id);if(first)refuge.unlockedNodes.Add(e.id);RefreshMapEntityStates();transferChoices.Clear();foreach(var id in e.destinations){var node=FindTransferNode(id);if(node!=null&&refuge.unlockedNodes.Contains(id)&&id!=e.id)transferChoices.Add(node);}Action ready=()=>{transferSelection=0;transferMenu=transferChoices.Count>0;};if(first||transferChoices.Count==0)worldDialogue.Begin(new[]{new WorldDialogueLine("SISTEMA",transferChoices.Count==0?"Ningún otro nodo disponible.":"Nodo registrado: "+e.displayName+".")},ready);else ready();}
 TransferNodeDefinition FindTransferNode(string id){if(refugeSettings!=null){var old=Array.Find(refugeSettings.nodes,n=>n.id==id);if(old!=null)return old;}if(ActiveMap==null||ActiveMap.entities==null)return null;var e=ActiveMap.entities.objects.Find(o=>o.kind==DungeonEntityKind.Teleport&&o.id==id);return e==null?null:new TransferNodeDefinition{id=e.id,displayName=e.displayName,cell=e.cell,arrivalHeading=e.heading};}
 void TravelMapDoor(DungeonMapEntity e){if(e.destinationMap==null||e.destinationMap==ActiveMap){WarpPlayer(e.destinationCell,e.heading);message=e.destinationRegionId;return;}var data=CaptureDungeonSave();data.cell=e.destinationCell;data.heading=e.heading;data.explored.Clear();var nextRoot=new GameObject("Dungeon — "+e.destinationMap.name);var next=nextRoot.AddComponent<DungeonPrototype>();JsonUtility.FromJsonOverwrite(JsonUtility.ToJson(this),next);next.mapSettings=e.destinationMap;next.dungeonRegions=e.destinationMap.regions;next.incomingMapTravel=data;Destroy(gameObject);}
 void ApplyMapTravel(){if(incomingMapTravel==null)return;incomingMapTravel.enemies=CaptureEnemyProgression();incomingMapTravel.triggeredEncounters=CaptureTriggeredEncounterIds();RestoreDungeonSave(incomingMapTravel);incomingMapTravel=null;}
 void DrawMapEntityPrompt(float width,float height){if(worldDialogue.Active||transferMenu||nodeDecision||IntroductionActive||battle||lost||pauseOpen)return;var e=NearbyMapEntity();if(e!=null)GUI.Box(new Rect(width/2-190,height-155,380,45),"[E] "+e.displayName);}
}
